package com.worksphere.controller; import com.worksphere.dto.auth.*; import com.worksphere.service.AuthService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s;public AuthController(AuthService x){s=x;} @PostMapping("/register") public AuthResponse register(@RequestBody RegisterRequest r){return s.register(r);} @PostMapping("/login") public AuthResponse login(@RequestBody LoginRequest r){return s.login(r);} }
